45206ba973d67862d4f9.css:
.simulation-.simulation-body {
    --blue: #1f6fb2;
    --blue-dark: #175a93;
    --beam: #5dade2;
    --red: #c0392b;
    --green: #1e8e3e;
    --green-bg: #e8f5ec;
    --red-bg: #fdecea;
    --dark: #2c2c2c;
    --gray: #6b7280;
    --bg: #f5f7fa;
    --panel: #ffffff;
    --border: #dfe3e8;
}

* { box-sizing: border-box; }

.simulation-body {
    font-family: "Segoe UI", Arial, Helvetica, sans-serif;
    background: var(--bg);
    color: var(--dark);
    margin: 0;
    padding: 24px;
}

.wrap {
    max-width: 1100px;
    margin: 0 auto;
}

/* ---------- header ---------- */

.quiz-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 16px;
    margin-bottom: 16px;
}

h1 {
    font-size: 22px;
    margin: 0 0 4px 0;
}

.subtitle {
    color: var(--gray);
    font-size: 14px;
}

/* ---------- panels ---------- */

.panel {
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 16px;
}

.panel h2 {
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--gray);
    margin: 0 0 12px 0;
}

.panel h2 .part-tag {
    color: var(--blue);
    margin-right: 6px;
}

.panel p.lead {
    margin: 0 0 12px 0;
    font-size: 14px;
    line-height: 1.5;
}

/* ---------- givens ---------- */

.givens {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-bottom: 12px;
}

.chip {
    background: #eef4fb;
    border: 1px solid #cfe0f1;
    color: var(--blue-dark);
    border-radius: 999px;
    padding: 5px 14px;
    font-size: 14px;
    font-weight: 600;
}

.convention {
    font-size: 12.5px;
    color: var(--gray);
    line-height: 1.5;
    margin-top: 6px;
}

#fbdSvg, .editor-svg {
    width: 100%;
    height: auto;
    display: block;
}

/* ---------- answer inputs ---------- */

.inputs-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
}

.field label {
    display: block;
    font-size: 13px;
    font-weight: 600;
    margin-bottom: 6px;
}

.field label small {
    display: block;
    font-weight: 400;
    color: var(--gray);
    font-size: 11.5px;
    margin-top: 1px;
}

.field .input-row {
    display: flex;
    align-items: center;
    gap: 8px;
}

.field input {
    width: 100%;
    padding: 8px 10px;
    border: 1.5px solid var(--border);
    border-radius: 7px;
    font-size: 15px;
    font-family: inherit;
}

.field input:focus {
    outline: none;
    border-color: var(--blue);
    box-shadow: 0 0 0 3px rgba(31, 111, 178, 0.15);
}

.field .unit {
    font-size: 13px;
    color: var(--gray);
    white-space: nowrap;
}

.field .fb {
    min-height: 18px;
    font-size: 12.5px;
    margin-top: 5px;
    line-height: 1.35;
}

.field.ok input { border-color: var(--green); background: var(--green-bg); }
.field.bad input { border-color: var(--red); background: var(--red-bg); }
.field.ok .fb { color: var(--green); }
.field.bad .fb { color: var(--red); }
.field .reveal { color: var(--green); font-weight: 600; }

/* ---------- drawing toolbar ---------- */

.toolbar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px 14px;
    margin-bottom: 8px;
}

.tool-group {
    display: flex;
    gap: 6px;
    flex-wrap: wrap;
}

.tool-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 12px;
    border: 1.5px solid var(--border);
    background: #fff;
    border-radius: 8px;
    font-size: 13px;
    font-weight: 600;
    font-family: inherit;
    color: var(--gray);
    cursor: pointer;
}

.tool-btn:hover { border-color: #b8c2cc; color: var(--dark); }

.tool-btn.active {
    background: var(--blue);
    border-color: var(--blue);
    color: #fff;
}

.editor-moment .tool-btn.active {
    background: var(--red);
    border-color: var(--red);
}

.tool-btn.action { color: var(--dark); }

.curve-opts {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 12.5px;
    color: var(--gray);
}

.curve-opts[hidden] { display: none; }

.curve-opts button {
    padding: 4px 10px;
    border: 1.5px solid var(--border);
    background: #fff;
    border-radius: 6px;
    font-size: 12.5px;
    font-family: inherit;
    cursor: pointer;
    color: var(--gray);
}

.curve-opts button.active {
    border-color: var(--dark);
    color: var(--dark);
    font-weight: 700;
}

.editor-readout {
    font-size: 12.5px;
    color: var(--gray);
    height: 18px;
    font-variant-numeric: tabular-nums;
}

.editor-svg { cursor: crosshair; touch-action: manipulation; }

.editor-caption {
    font-size: 12.5px;
    color: var(--gray);
    margin-top: 4px;
}

.editor-msg {
    min-height: 20px;
    margin-top: 6px;
    font-size: 13px;
    line-height: 1.4;
}

.editor-msg.info { color: var(--gray); }
.editor-msg.warn { color: #a15c00; }
.editor-msg.ok { color: var(--green); font-weight: 600; }
.editor-msg.bad { color: var(--red); }

/* ---------- buttons / actions ---------- */

.btn {
    padding: 9px 18px;
    border-radius: 8px;
    border: 1.5px solid var(--border);
    background: #fff;
    color: var(--dark);
    font-size: 14px;
    font-weight: 600;
    font-family: inherit;
    cursor: pointer;
    white-space: nowrap;
}

.btn:hover { border-color: #b8c2cc; }

.btn.primary {
    background: var(--blue);
    border-color: var(--blue);
    color: #fff;
}

.btn.primary:hover { background: var(--blue-dark); }

.actions {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    align-items: center;
}

.summary {
    margin-top: 14px;
    font-size: 14px;
    line-height: 1.6;
}

.summary .banner {
    padding: 10px 14px;
    border-radius: 8px;
    font-weight: 600;
    margin-bottom: 8px;
}

.summary .banner.all-ok { background: var(--green-bg); color: var(--green); }
.summary .banner.partial { background: #fff6e5; color: #8a5a00; }

.summary ul {
    margin: 0;
    padding-left: 0;
    list-style: none;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 4px 16px;
}

.summary li.ok { color: var(--green); }
.summary li.bad { color: var(--red); }

@media (max-width: 800px) {
    .simulation-body { padding: 14px; }
    .inputs-grid { grid-template-columns: repeat(2, 1fr); }
    .summary ul { grid-template-columns: repeat(2, 1fr); }
}

.how-to summary { cursor: pointer; list-style: none; }
.how-to summary::-webkit-details-marker { display: none; }
.how-to summary h2 { display: inline; margin: 0; }
.how-to summary::after { content: "  (click to show or hide)"; font-size: 12px; color: var(--gray); }
.how-to details > *:not(summary) { margin-top: 12px; }
.how-list { margin: 0; padding-left: 20px; font-size: 14px; line-height: 1.6; }
.how-list li { margin-bottom: 4px; }

