    font-size: 14px;
    line-height: 1.5;
}

/* ---------- givens ---------- */

.givens {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-bottom: 12px;
}

.chip {
    background: #eef4fb;
    border: 1px solid #cfe0f1;
    color: var(--blue-dark);
    border-radius: 999px;
    padding: 5px 14px;
    font-size: 14px;
    font-weight: 600;
}

.convention {
    font-size: 12.5px;
    color: var(--gray);
    line-height: 1.5;
    margin-top: 6px;
}

#fbdSvg, .editor-svg {
    width: 100%;
    height: auto;
    display: block;
}

/* ---------- answer inputs ---------- */

.inputs-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
}

.field label {
    display: block;
    font-size: 13px;
    font-weight: 600;
    margin-bottom: 6px;
}

.field label small {
    display: block;
    font-weight: 400;
    color: var(--gray);
    font-size: 11.5px;
    margin-top: 1px;
}

.field .input-row {
    display: flex;
    align-items: center;
    gap: 8px;
}

