    font-size: 12.5px;
    color: var(--gray);
    height: 18px;
    font-variant-numeric: tabular-nums;
}

.editor-svg { cursor: crosshair; touch-action: manipulation; }

.editor-caption {
    font-size: 12.5px;
    color: var(--gray);
    margin-top: 4px;
}

.editor-msg {
    min-height: 20px;
    margin-top: 6px;
    font-size: 13px;
    line-height: 1.4;
}

.editor-msg.info { color: var(--gray); }
.editor-msg.warn { color: #a15c00; }
.editor-msg.ok { color: var(--green); font-weight: 600; }
.editor-msg.bad { color: var(--red); }

/* ---------- buttons / actions ---------- */

.btn {
    padding: 9px 18px;
    border-radius: 8px;
    border: 1.5px solid var(--border);
    background: #fff;
    color: var(--dark);
    font-size: 14px;
    font-weight: 600;
    font-family: inherit;
    cursor: pointer;
    white-space: nowrap;
}

.btn:hover { border-color: #b8c2cc; }

.btn.primary {
    background: var(--blue);
    border-color: var(--blue);
    color: #fff;
}

.btn.primary:hover { background: var(--blue-dark); }

.actions {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    align-items: center;
}

.summary {
    margin-top: 14px;
    font-size: 14px;
    line-height: 1.6;
}

.summary .banner {
    padding: 10px 14px;
    border-radius: 8px;
    font-weight: 600;
    margin-bottom: 8px;
}

.summary .banner.all-ok { background: var(--green-bg); color: var(--green); }
.summary .banner.partial { background: #fff6e5; color: #8a5a00; }

.summary ul {
    margin: 0;
    padding-left: 0;
    list-style: none;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 4px 16px;
}

.summary li.ok { color: var(--green); }
.summary li.bad { color: var(--red); }

@media (max-width: 800px) {
    .simulation-body { padding: 14px; }
    .inputs-grid { grid-template-columns: repeat(2, 1fr); }
    .summary ul { grid-template-columns: repeat(2, 1fr); }
}

.how-to summary { cursor: pointer; list-style: none; }
.how-to summary::-webkit-details-marker { display: none; }
.how-to summary h2 { display: inline; margin: 0; }
.how-to summary::after { content: "  (click to show or hide)"; font-size: 12px; color: var(--gray); }
.how-to details > *:not(summary) { margin-top: 12px; }
.how-list { margin: 0; padding-left: 20px; font-size: 14px; line-height: 1.6; }
.how-list li { margin-bottom: 4px; }

