/* ------------------------------------------------------------------ *
 *  FBD practice – ball on an incline
 * ------------------------------------------------------------------ */

.simulation-.simulation-body {
  --bg: #f4f5f8;
  --surface: #ffffff;
  --text: #1b2130;
  --muted: #5b6577;
  --border: #d9dde5;
  --wedge: #e2e6ed;
  --line: #2a3242;
  --ball: rgba(110, 135, 185, 0.18);
  --ground: #2f9e5b;
  --hatch: #c3c9d4;

  --c-w: #475569;
  --c-n: #2563eb;
  --c-f: #d97706;
  --c-t: #7c3aed;

  --good: #15803d;
  --good-bg: #e7f6ec;
  --bad: #d92d20;
  --bad-bg: #fdecea;
  --accent: #2563eb;

  color-scheme: light;
  --radius: 14px;
  --shadow: 0 1px 2px rgba(16, 24, 40, 0.06), 0 2px 6px rgba(16, 24, 40, 0.06);
}

.simulation-body[data-theme="dark"] {
  color-scheme: dark;
  --bg: #12151c;
  --surface: #1b2029;
  --text: #e8ebf1;
  --muted: #9aa4b6;
  --border: #2f3746;
  --wedge: #2b3342;
  --line: #cfd6e4;
  --ball: rgba(140, 165, 215, 0.2);
  --ground: #46c47f;
  --hatch: #333b4b;

  --c-w: #cbd5e1;
  --c-n: #6ea0ff;
  --c-f: #fbbf24;
  --c-t: #b79bff;

  --good: #4ade80;
  --good-bg: rgba(74, 222, 128, 0.12);
  --bad: #ff7b72;
  --bad-bg: rgba(255, 123, 114, 0.12);
  --accent: #6ea0ff;
  --shadow: none;
}

* { box-sizing: border-box; }

.simulation-body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  line-height: 1.45;
}

.app {
  max-width: 1120px;
  margin: 0 auto;
  padding: 20px 16px 40px;
}

/* ---------- header ---------- */

.top {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px 24px;
  margin-bottom: 14px;
}
.eyebrow {
  margin: 0 0 2px;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 600;
}
h1 { margin: 0; font-size: 26px; line-height: 1.15; }
h2 {
  margin: 0 0 6px;
  font-size: 17px;
  display: flex;
  align-items: center;
  gap: 8px;
}
h3 { margin: 0 0 8px; font-size: 15px; display: flex; align-items: center; gap: 8px; }

.controls { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }

.seg {
  display: inline-flex;
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
  background: var(--surface);
}
.seg button {
  border: 0;
  background: transparent;
  color: var(--text);
  padding: 8px 16px;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}
.seg button + button { border-left: 1px solid var(--border); }
.seg button[aria-pressed="true"] { background: var(--accent); color: #fff; }
.seg button:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }

.btn {
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  padding: 8px 14px;
  border-radius: 10px;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}
.btn:hover:not(:disabled) { border-color: var(--accent); }
.btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.btn.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn:disabled { opacity: 0.45; cursor: not-allowed; }

/* ---------- cards / layout ---------- */

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px 18px;
}

.statement { margin-bottom: 14px; font-size: 16px; }

.layout {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(300px, 0.9fr);
  gap: 14px;
  align-items: start;
}
@media (max-width: 900px) {
  .layout { grid-template-columns: minmax(0, 1fr); }
}

.stage-card { padding: 8px; }
.side { display: grid; gap: 14px; }

.num {
  display: inline-grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  font-size: 13px;
}
.hint { margin: 0 0 12px; color: var(--muted); font-size: 14px; }

.step.locked { opacity: 0.6; }
.step.locked .num { background: var(--muted); }

.actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }

.msg { margin: 10px 0 0; min-height: 1.3em; font-size: 14px; font-weight: 600; }
.msg.ok { color: var(--good); }
.msg.bad { color: var(--bad); }

fieldset { border: 0; padding: 0; margin: 0; min-width: 0; }

/* ---------- force chips ---------- */

.chips { display: grid; gap: 8px; }
.chip {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  text-align: left;
  border: 1.5px solid var(--border);
  background: var(--surface);
  color: var(--text);
  border-radius: 10px;
  padding: 9px 12px;
  font: inherit;
  cursor: pointer;
}
.chip:hover:not(:disabled) { border-color: var(--fc); }
.chip:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.chip[aria-pressed="true"] { border-color: var(--fc); background: color-mix(in srgb, var(--fc) 10%, var(--surface)); }
.chip:disabled { cursor: default; }
.chip .sym { font-weight: 800; font-style: italic; color: var(--fc); min-width: 1.1em; }
.chip .status { margin-left: auto; font-size: 13px; font-weight: 700; }
.chip.ok .status { color: var(--good); }
.chip.bad .status, .chip.missing .status { color: var(--bad); }
.chip.ok { border-color: var(--good); }
.chip.bad, .chip.missing { border-color: var(--bad); }

.swatch { width: 12px; height: 12px; border-radius: 50%; background: var(--fc); flex: none; }

.f-W { --fc: var(--c-w); }
.f-N { --fc: var(--c-n); }
.f-f { --fc: var(--c-f); }
.f-T { --fc: var(--c-t); }

/* ---------- step 2 form ---------- */

.comp-card {
  border: 1px solid var(--border);
  border-left: 4px solid var(--fc);
  border-radius: 10px;
  padding: 12px 14px;
  margin-bottom: 10px;
}
.comp-card .sym { font-style: italic; color: var(--fc); }
.field { display: grid; gap: 4px; font-size: 14px; margin-bottom: 10px; }
.inp { display: inline-flex; align-items: center; gap: 6px; }

.eq-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 8px;
  font-size: 15px;
  margin-bottom: 8px;
}
.eq-row .dirgrp { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; margin-left: 6px; }
.eq-row .dir { color: var(--muted); font-size: 13px; }

input[type="number"], select {
  font: inherit;
  color: var(--text);
  background: var(--surface);
  border: 1.5px solid var(--border);
  border-radius: 8px;
  padding: 6px 8px;
}
input[type="number"] { width: 92px; }
input:focus-visible, select:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
input.ok, select.ok { border-color: var(--good); background: var(--good-bg); }
input.bad, select.bad { border-color: var(--bad); background: var(--bad-bg); }

/* ---------- SVG ---------- */

#stage { width: 100%; height: auto; display: block; user-select: none; -webkit-user-select: none; }
.hatch-line { stroke: var(--hatch); stroke-width: 2; }
.ground-line { stroke: var(--ground); stroke-width: 3.5; stroke-linecap: round; }
.wedge { fill: var(--wedge); }
.slope-line { stroke: var(--line); stroke-width: 3; stroke-linecap: round; }
.ball { fill: var(--ball); stroke: var(--line); stroke-width: 2.5; }
.rope { stroke: var(--muted); stroke-width: 3; stroke-linecap: round; }
.anchor { fill: var(--muted); }
.given-arc { fill: none; stroke: var(--muted); stroke-width: 1.8; }
.given-ref { stroke: var(--muted); stroke-width: 1.4; stroke-dasharray: 5 4; opacity: 0.8; }
.given-label {
  fill: var(--text);
  font-size: 14px;
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: central;
}

.arrow line { stroke: var(--fc); stroke-width: 4; stroke-linecap: round; }
.arrow polygon { fill: var(--fc); }
.arrow .tail-dot { fill: var(--fc); }
.arrow.ok line { stroke: var(--good); }
.arrow.ok polygon, .arrow.ok .tail-dot { fill: var(--good); }
.arrow.bad line { stroke: var(--bad); }
.arrow.bad polygon, .arrow.bad .tail-dot { fill: var(--bad); }

.f-label {
  fill: var(--fc);
  font-size: 18px;
  font-weight: 800;
  font-style: italic;
  text-anchor: middle;
  dominant-baseline: central;
  paint-order: stroke;
  stroke: var(--surface);
  stroke-width: 4px;
  stroke-linejoin: round;
}

.handle { cursor: grab; touch-action: none; outline: none; }
.handle:active { cursor: grabbing; }
.handle .hit { fill: transparent; stroke: none; }
.handle .vis { fill: var(--surface); stroke: var(--fc); stroke-width: 3; }
.handle:hover .vis, .handle:focus-visible .vis { fill: var(--fc); }
.handle:focus-visible .hit { stroke: var(--accent); stroke-width: 2; stroke-dasharray: 3 3; }

.axis-line { stroke: var(--fc); stroke-width: 1.6; stroke-dasharray: 6 4; opacity: 0.75; }
.arc { fill: none; stroke: var(--fc); stroke-width: 2.8; }
.arc-label {
  fill: var(--fc);
  font-size: 15px;
  font-weight: 800;
  text-anchor: middle;
  dominant-baseline: central;
  paint-order: stroke;
  stroke: var(--surface);
  stroke-width: 4px;
  stroke-linejoin: round;
}
.arc-label.ok { fill: var(--good); }
.arc-label.bad { fill: var(--bad); }

/* ---------- Nx / Ny component step, echoed angle ---------- */

[hidden] { display: none !important; }

.f-Nx, .f-Ny { --fc: var(--c-n); }

.arrow.dashed line { stroke-dasharray: 9 6; stroke-width: 3.5; stroke-linecap: butt; }
.f-label .sub { font-size: 13px; }
.chip .sym sub { font-size: 0.7em; }

.eq-row .paren { display: inline-flex; align-items: center; gap: 4px; }
.echo {
  display: inline-block;
  min-width: 56px;
  padding: 3px 8px;
  text-align: center;
  font-size: 14px;
  color: var(--muted);
  border: 1.5px dashed var(--border);
  border-radius: 8px;
}
.echo.filled {
  color: var(--text);
  font-weight: 700;
  border-style: solid;
  border-color: var(--fc);
}

/* ---------- two angles on Easy: colour-coded (teal = from the vertical, amber = from the horizontal) ---------- */

.simulation-.simulation-body { --c-ang-v: #0f9d8a; }
.simulation-body[data-theme="dark"] { --c-ang-v: #4fd1c0; }

.ang-v { --fc: var(--c-ang-v); }
.ang-h { --fc: var(--c-f); }
.field .swatch { display: inline-block; vertical-align: middle; margin-right: 2px; }
.echo.filled.ang-v, .echo.filled.ang-h { border-color: var(--fc); }

