/* ------------------------------------------------------------------ *
 *  FBD practice – ball on an incline
 * ------------------------------------------------------------------ */

.simulation-.simulation-body {
  --bg: #f4f5f8;
  --surface: #ffffff;
  --text: #1b2130;
  --muted: #5b6577;
  --border: #d9dde5;
  --wedge: #e2e6ed;
  --line: #2a3242;
  --ball: rgba(110, 135, 185, 0.18);
  --ground: #2f9e5b;
  --hatch: #c3c9d4;

  --c-w: #475569;
  --c-n: #2563eb;
  --c-f: #d97706;
  --c-t: #7c3aed;
  --c-t1: #7c3aed;
  --c-t2: #0f9d8a;
  --c-t3: #e0457b;

  --good: #15803d;
  --good-bg: #e7f6ec;
  --bad: #d92d20;
  --bad-bg: #fdecea;
  --accent: #2563eb;

  color-scheme: light;
  --radius: 14px;
  --shadow: 0 1px 2px rgba(16, 24, 40, 0.06), 0 2px 6px rgba(16, 24, 40, 0.06);
}

.simulation-body[data-theme="dark"] {
  color-scheme: dark;
  --bg: #12151c;
  --surface: #1b2029;
  --text: #e8ebf1;
  --muted: #9aa4b6;
  --border: #2f3746;
  --wedge: #2b3342;
  --line: #cfd6e4;
  --ball: rgba(140, 165, 215, 0.2);
  --ground: #46c47f;
  --hatch: #333b4b;

  --c-w: #cbd5e1;
  --c-n: #6ea0ff;
  --c-f: #fbbf24;
  --c-t: #b79bff;
  --c-t1: #b79bff;
  --c-t2: #4fd1c0;
  --c-t3: #ff7aa8;

  --good: #4ade80;
  --good-bg: rgba(74, 222, 128, 0.12);
  --bad: #ff7b72;
  --bad-bg: rgba(255, 123, 114, 0.12);
  --accent: #6ea0ff;
  --shadow: none;
}

* { box-sizing: border-box; }

.simulation-body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  line-height: 1.45;
}

.app {
  max-width: 1120px;
  margin: 0 auto;
  padding: 20px 16px 40px;
}

/* ---------- header ---------- */

.top {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px 24px;
  margin-bottom: 14px;
}
.eyebrow {
  margin: 0 0 2px;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 600;
}
h1 { margin: 0; font-size: 26px; line-height: 1.15; }
h2 {
  margin: 0 0 6px;
  font-size: 17px;
  display: flex;
  align-items: center;
  gap: 8px;
}
h3 { margin: 0 0 8px; font-size: 15px; display: flex; align-items: center; gap: 8px; }

.controls { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }

.seg {
  display: inline-flex;
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
  background: var(--surface);
}
.seg button {
  border: 0;
  background: transparent;
  color: var(--text);
  padding: 8px 16px;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}
.seg button + button { border-left: 1px solid var(--border); }
.seg button[aria-pressed="true"] { background: var(--accent); color: #fff; }
.seg button:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }

.btn {
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  padding: 8px 14px;
  border-radius: 10px;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}
.btn:hover:not(:disabled) { border-color: var(--accent); }
.btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.btn.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn:disabled { opacity: 0.45; cursor: not-allowed; }

/* ---------- cards / layout ---------- */

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px 18px;
}

.statement { margin-bottom: 14px; font-size: 16px; }

.layout {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(300px, 0.9fr);
  gap: 14px;
  align-items: start;
}
@media (max-width: 900px) {
  .layout { grid-template-columns: minmax(0, 1fr); }
}

.stage-card { padding: 8px; }
.side { display: grid; gap: 14px; }

.num {
  display: inline-grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  font-size: 13px;
}
.hint { margin: 0 0 12px; color: var(--muted); font-size: 14px; }

.step.locked { opacity: 0.6; }
.step.locked .num { background: var(--muted); }

.actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }

.msg { margin: 10px 0 0; min-height: 1.3em; font-size: 14px; font-weight: 600; }
.msg.ok { color: var(--good); }
.msg.bad { color: var(--bad); }

fieldset { border: 0; padding: 0; margin: 0; min-width: 0; }

/* ---------- force chips ---------- */

.chips { display: grid; gap: 8px; }
.chip {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  text-align: left;
  border: 1.5px solid var(--border);
  background: var(--surface);
  color: var(--text);
  border-radius: 10px;
  padding: 9px 12px;
  font: inherit;
  cursor: pointer;
}
.chip:hover:not(:disabled) { border-color: var(--fc); }
.chip:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.chip[aria-pressed="true"] { border-color: var(--fc); background: color-mix(in srgb, var(--fc) 10%, var(--surface)); }
.chip:disabled { cursor: default; }
.chip .sym { font-weight: 800; font-style: italic; color: var(--fc); min-width: 1.1em; }
.chip .status { margin-left: auto; font-size: 13px; font-weight: 700; }
.chip.ok .status { color: var(--good); }
.chip.bad .status, .chip.missing .status { color: var(--bad); }
.chip.ok { border-color: var(--good); }
.chip.bad, .chip.missing { border-color: var(--bad); }

.swatch { width: 12px; height: 12px; border-radius: 50%; background: var(--fc); flex: none; }

.f-W { --fc: var(--c-w); }
.f-N { --fc: var(--c-n); }
.f-f { --fc: var(--c-f); }
.f-T { --fc: var(--c-t); }
.f-T1 { --fc: var(--c-t1); }
.f-T2 { --fc: var(--c-t2); }
.f-T3 { --fc: var(--c-t3); }
.f-TL { --fc: var(--c-t); }
.f-TR { --fc: var(--c-t); }

/* ---------- step 2 form ---------- */

