  border-radius: 10px;
  padding: 12px 14px;
  margin-bottom: 10px;
}
.comp-card .sym { font-style: italic; color: var(--fc); }
.field { display: grid; gap: 4px; font-size: 14px; margin-bottom: 10px; }
.inp { display: inline-flex; align-items: center; gap: 6px; }

.eq-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 8px;
  font-size: 15px;
  margin-bottom: 8px;
}
